const C = $('Config').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const iso = d => d.toISOString().slice(0,10);
const parse = v => { if (!v && v !== 0) return null; if (typeof v === 'number') { const d = new Date(Date.UTC(1899,11,30) + v*864e5); return isNaN(d) ? null : d; } const d = new Date(v); return isNaN(d) ? null : d; };
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const days = (a, b) => Math.floor((b - a) / 864e5);
const fill = (t, o) => t.replace(/\{(\w+)\}/g, (_, k) => (o[k] ?? ''));

const b = $('Twilio call status').first().json.body || {};
// Forwarded calls (<Dial>): the forwarded leg's result is in DialCallStatus; CallStatus is then just 'in-progress'
const st = String(b.DialCallStatus || b.CallStatus || '').toLowerCase();
// Voicemail picked up the forwarded call (Answering Machine Detection) -> still a missed call
const machine = String(b.AnsweredBy || '').toLowerCase().startsWith('machine');
if ((!['no-answer','busy','failed','canceled'].includes(st) && !machine) || !b.From) return [];
// Blocked / anonymous caller ID (Twilio sends e.g. +266696687 = 'ANONYMOUS' on a keypad): no number to text
const raw = String(b.From), dg = raw.replace(/\D/g, '');
const blocked = /anonymous|restricted|private|unknown|unavailable|blocked/i.test(raw) || dg.length < 7 ||
  ['266696687','7378742833','7748283','8656696','86282452253','2562533'].includes(dg);
return [{ json: { caller: raw, status: machine ? 'voicemail' : st, blocked } }];

const C = $('Config').first().json;
const today = new Date(); today.setHours(0,0,0,0);
const iso = d => d.toISOString().slice(0,10);
const parse = v => { if (!v && v !== 0) return null; if (typeof v === 'number') { const d = new Date(Date.UTC(1899,11,30) + v*864e5); return isNaN(d) ? null : d; } const d = new Date(v); return isNaN(d) ? null : d; };
const num = v => { const n = Number(String(v ?? '').replace(/[^0-9.-]/g, '')); return isNaN(n) ? 0 : n; };
const days = (a, b) => Math.floor((b - a) / 864e5);
const fill = (t, o) => t.replace(/\{(\w+)\}/g, (_, k) => (o[k] ?? ''));

const m = $('Was it missed?').first().json;
const now = new Date();
const digits = s => String(s || '').replace(/\D/g, '').slice(-10);
// 1) Repeat call: same caller texted within dedupeMinutes -> no second text
const windowMs = Number(C.dedupeMinutes || 30) * 6e4;
const dup = $input.all().map(i => i.json).some(r => { const t = parse(r['Time']);
  return digits(r['Caller']) === digits(m.caller) && String(r['Text sent']) === 'Yes' && t && (Date.now() - t) < windowMs; });
// 2) Business time in the business's own timezone
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-US', { timeZone: C.timezone || 'America/New_York', weekday: 'short', hour: 'numeric', hourCycle: 'h23' })
  .formatToParts(now).map(p => [p.type, p.value]));
const hour = Number(parts.hour), day = parts.weekday;
const open = String(C.openDays || '').split(',').map(x => x.trim()).includes(day) && hour >= Number(C.openHour) && hour < Number(C.closeHour);
const qs = Number(C.quietStart), qe = Number(C.quietEnd);
const em = String(C.emergencyLine || '').trim();
// Quiet hours never apply during open hours, and are skipped when an emergency line is set
const quiet = !open && !em && (qs > qe ? (hour >= qs || hour < qe) : (hour >= qs && hour < qe));
let send = true, text = fill(C.text, { business: C.business }), note = 'Open hours';
if (m.blocked) { send = false; note = 'Blocked caller ID - cannot text; call back if they left a voicemail'; }
else if (dup) { send = false; note = 'Repeat call within ' + (C.dedupeMinutes || 30) + ' min - no second text'; }
else if (open) { /* open hours always win */ }
else if (quiet) { send = false; note = 'Quiet hours - no text sent; call back when you open'; }
else if (em) { text = fill(C.afterHoursText, { business: C.business }) + ' ' + fill(C.emergencyText || 'Emergency? Call our on-call line now: {emergencyLine}', { business: C.business, emergencyLine: em }); note = 'After hours - closed message + emergency line sent'; }
else { text = fill(C.afterHoursText, { business: C.business }); note = 'After hours - closed message sent'; }
return [{ json: { ...m, send, text, note } }];
